<script lang="ts">
  import { onMount,onDestroy } from 'svelte';
  import type { LibraryEntry } from './story';
  import type { SetupDraft } from './setup';
  import type { WorkflowMode } from './story-workflow/contracts';
  import { builtInStoryNodes,defaultStoryWorkflow } from './story-workflow/default-graph';
  import { workflowModeName,workflowNodeName } from './story-workflow/presentation';
  import { addBuiltIn,removeBuiltIn,supportedNode,assessPreset,exportPreset,importPreset,type PresetContent,type WorkflowPreset } from './story-workflow/presets';
  import { inspectExecutableWorkflow } from './story-workflow/compile';
  let {busy=$bindable(false),canGenerate=false,onDirty,onBack}:{busy?:boolean;canGenerate?:boolean;onDirty:(value:boolean)=>void;onBack:()=>void}=$props();
  const fresh=(mode:WorkflowMode):PresetContent=>({name:`${workflowModeName(mode)} preset`,description:'',definition:defaultStoryWorkflow(mode)});
  let content=$state(fresh('continue')),baseline=$state(JSON.stringify(fresh('continue'))),saved=$state<WorkflowPreset|null>(null),presets=$state<WorkflowPreset[]>([]);
  let stories=$state<LibraryEntry[]>([]),setups=$state<SetupDraft[]>([]),loading=$state(false),loaded=$state(false),problem=$state(''),note=$state(''),mode=$state<WorkflowMode>('continue'),selected=$state('source'),newType=$state('model');
  let fromNode=$state('source'),fromPort=$state('source'),toNode=$state('prepare'),toPort=$state('source');
  let controller:AbortController|undefined,request:{key:string;id:string}|null=null;
  const dirty=$derived(JSON.stringify(content)!==baseline),graph=$derived(content.definition),assessment=$derived(assessPreset(graph)),node=$derived(graph.nodes.find(node=>node.id===selected));
  const eligibility=$derived(inspectExecutableWorkflow(graph));
  const outputs=$derived(Object.entries(supportedNode(graph.nodes.find(node=>node.id===fromNode)?.type??'')?.outputs??{}));
  const inputs=$derived(Object.entries(supportedNode(graph.nodes.find(node=>node.id===toNode)?.type??'')?.inputs??{}));
  const type=$derived(outputs.find(([name])=>name===fromPort)?.[1].type);
  const compatible=$derived(inputs.filter(([,port])=>port.type===type));
  $effect(()=>onDirty(dirty));
  onDestroy(()=>{controller?.abort();onDirty(false);});
  async function read(response:Response){const result=await response.json();if(!response.ok)throw new Error(result.error||'Workflow presets are unavailable.');return result;}
  async function refresh(){if(loading||busy)return;controller?.abort();controller=new AbortController();loading=true;problem='';try{const results=await Promise.all([fetch('/api/story-workflow-presets',{signal:controller.signal}).then(read),fetch('/api/stories',{signal:controller.signal}).then(read),fetch('/api/setups',{signal:controller.signal}).then(read)]);presets=results[0].presets;stories=results[1];setups=results[2];loaded=true;}catch(error){if(!controller.signal.aborted)problem=error instanceof Error?error.message:'Could not load presets. Your draft is kept.';}finally{loading=false;}}
  onMount(()=>{void refresh();});
  function mayLeave(){return !dirty||confirm('Discard the unsaved workflow preset edits? Save draft first to keep them.');}
  function accept(value:WorkflowPreset){saved=value;content=structuredClone(value.content);baseline=JSON.stringify(content);selected=content.definition.nodes[0]?.id??'';request=null;}
  function newDraft(){if(busy||!mayLeave())return;saved=null;content=fresh(mode);baseline=JSON.stringify(content);selected='source';problem='';note='New draft from the default graph. Normal generation still uses the default workflow.';request=null;}
  async function open(id:string){if(busy||loading||!mayLeave())return;busy=true;problem='';try{accept(await read(await fetch(`/api/story-workflow-presets/${id}`)));note='Saved draft loaded.';}catch(error){problem=error instanceof Error?error.message:'Could not load preset. Your draft is kept.';}finally{busy=false;}}
  async function save(){if(busy||loading)return;problem='';note='';const body={expectedRevision:saved?.revision??0,content:$state.snapshot(content)},key=JSON.stringify({id:saved?.id??null,...body});if(request?.key!==key)request={key,id:crypto.randomUUID()};busy=true;
    try{const result=await read(await fetch(saved?`/api/story-workflow-presets/${saved.id}`:'/api/story-workflow-presets',{method:saved?'PATCH':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...body,requestId:request.id})}));accept(result);note='Workflow draft saved.';}catch(error){problem=error instanceof Error?error.message:'Could not save preset. Your draft is kept.';}finally{busy=false;}if(!problem)await refresh();}
  function add(){try{content.definition=addBuiltIn($state.snapshot(graph),newType);selected=content.definition.nodes.at(-1)!.id;note='Node added. Connect its required inputs.';}catch(error){problem=String(error instanceof Error?error.message:error);}}
  function remove(){if(!node)return;try{content.definition=removeBuiltIn($state.snapshot(graph),node.id);selected=content.definition.nodes[0]?.id??'';note='Node and its connections removed from this draft.';}catch(error){problem=String(error instanceof Error?error.message:error);}}
  function connect(){if(!type||!compatible.some(([name])=>name===toPort)){problem='Choose compatible typed ports.';return;}const edge={from:{node:fromNode,port:fromPort},to:{node:toNode,port:toPort}};if(graph.edges.some(e=>JSON.stringify(e)===JSON.stringify(edge))){problem='That connection already exists.';return;}if(graph.edges.length>=500){problem='A draft supports at most 500 connections.';return;}graph.edges.push(edge);problem='';note='Connection added. Review validation below.';}
  function download(){try{const text=JSON.stringify(exportPreset($state.snapshot(content)),null,2),url=URL.createObjectURL(new Blob([text],{type:'application/json'})),link=document.createElement('a');link.href=url;link.download='story-workflow-preset.json';link.click();URL.revokeObjectURL(url);note='Draft exported. Source bindings and unavailable model references are detached for portability.';}catch(error){problem=error instanceof Error?error.message:'Could not export this draft.';}}
  async function upload(file:File|undefined){if(!file||busy)return;if(!mayLeave())return;problem='';busy=true;try{if(file.size>1_000_000)throw new Error('Choose a workflow preset JSON smaller than 1 MB.');const imported=importPreset(JSON.parse(await file.text()));saved=null;content=imported;baseline='';selected=content.definition.nodes[0]?.id??'';request=null;note='Imported as an unsaved draft. Review validation and choose source bindings.';}catch{problem='Could not import this preset. Use version-1 workflow preset JSON with supported fields and no credentials or copied story data. Your draft is kept.';}finally{busy=false;}}
</script>

<main class="full-view preset-editor">
  <div class="eyebrow">Story workflow authoring</div><h1>Workflow presets</h1>
  <p>Edit and save graphs built from supported nodes. Select an eligible saved preset in an opening, continuation or rewrite workflow selector to use it. Generation uses the default workflow until you explicitly choose a preset.</p>
  <div class="row"><button onclick={onBack} disabled={busy}>Back to workflow history</button><button onclick={refresh} disabled={busy||loading}>{loading?'Loading presets…':'Refresh preset library'}</button></div>
  {#if problem}<p class="notice" role="alert">{problem}</p>{/if}{#if note}<p role="status">{note}</p>{/if}
  <section aria-label="Preset library"><h2>Saved drafts</h2><div class="preset-list">{#each presets as preset (preset.id)}<button aria-pressed={saved?.id===preset.id} onclick={()=>open(preset.id)} disabled={busy||loading}>{preset.content.name} · revision {preset.revision}</button>{:else}<p class="muted">{loaded?'No saved presets yet. Start from a default graph below.':'Load the preset library to see saved drafts.'}</p>{/each}</div></section>
  <fieldset disabled={busy||loading}>
    <div class="row"><label>Default template<select aria-label="Default template" bind:value={mode}><option value="opening">Opening</option><option value="continue">Continuation</option><option value="replace">Latest rewrite</option></select></label><button type="button" onclick={newDraft}>New from default</button></div>
    <div class="form-grid"><label>Preset name<input bind:value={content.name} required maxlength="160" /></label><label>Description<textarea bind:value={content.description} maxlength="2000"></textarea></label></div>
    <p class="muted">{workflowModeName(graph.mode)} · {saved?`Saved revision ${saved.revision}`:'New draft'} · {dirty?'Unsaved edits':'Draft matches loaded values'}</p>
    <div class="row"><button class="primary" onclick={save} disabled={!content.name.trim()||Boolean(saved&&!dirty)}>Save draft</button>{#if saved}<button onclick={()=>open(saved!.id)}>Reload saved preset</button>{/if}<button onclick={download}>Export draft JSON</button></div>
    <label>Import preset JSON<input type="file" accept=".json,application/json" onchange={event=>{const file=event.currentTarget.files?.[0];event.currentTarget.value='';void upload(file);}} /></label>
    <section aria-label="Workflow validation"><h2>Draft validation</h2><p role="status">{assessment.structuralValid?'Graph structure is valid.':'Graph needs changes before execution.'}</p><ul>{#each assessment.issues as issue}<li>{issue.message}</li>{/each}{#each assessment.bindings as issue}<li>{issue.message}</li>{/each}</ul><h3>Execution eligibility</h3><p>{eligibility.eligible?'This graph keeps the supported built-in check path. Saved source/model bindings are checked again before execution.':'This graph can be saved as a draft but is outside the executable subset.'}</p><p class="muted">The executable subset keeps all built-in stages and IDs, with one to eight connected model nodes using the configured text profile. Check-branch changes remain drafts.</p>{#if assessment.structuralValid}<ul>{#each eligibility.issues as issue}<li>{issue.message}</li>{/each}</ul>{/if}{#if !canGenerate}<p class="muted">No text model is currently configured. Save a model in Settings before execution.</p>{/if}</section>
    <section aria-label="Preset bindings"><h2>Source and model references</h2><p class="muted">Bindings identify saved sources and a configured model profile. They copy no world records, prompts or credentials. Availability and source revisions are checked again before provider work.</p>
      {#each graph.bindings as binding,index (`${binding.name}:${index}`)}
        {#if binding.kind==='source'}{@const options=binding.sourceKind==='story'?stories.map(row=>({id:row.id,title:row.title})):setups.filter(row=>!row.storyId).map(row=>({id:row.id,title:row.plan?.title||row.input.title||'Untitled setup'}))}
          <label>{binding.name} · {binding.sourceKind}<select aria-label={`Source binding ${binding.name}`} value={binding.sourceId??''} onchange={event=>{binding.sourceId=event.currentTarget.value||undefined;}}><option value="">Unbound — choose saved source</option>{#if binding.sourceId&&!options.some(row=>row.id===binding.sourceId)}<option value={binding.sourceId}>Unavailable saved source</option>{/if}{#each options as source}<option value={source.id}>{source.title}</option>{/each}</select></label>
          {#if binding.sourceId&&!options.some(row=>row.id===binding.sourceId)}<p class="notice">This saved source is unavailable. Choose another source or leave it unbound.</p>{/if}
        {:else}<label>{binding.name} · model<select aria-label={`Model binding ${binding.name}`} bind:value={binding.connectionRef}>{#if !['configured-text','unbound'].includes(binding.connectionRef)}<option value={binding.connectionRef}>Unavailable connection reference</option>{/if}<option value="configured-text">Configured text profile (Settings)</option><option value="unbound">Unbound</option></select></label>{/if}
      {/each}
    </section>
    <div class="editor-columns">
      <section aria-label="Draft nodes"><h2>Built-in nodes</h2><label>Add node type<select aria-label="Add node type" bind:value={newType}>{#each Object.keys(builtInStoryNodes) as type}<option value={type}>{workflowNodeName(type)}</option>{/each}</select></label><button onclick={add} disabled={graph.nodes.length>=100}>Add built-in node</button><div class="node-list">{#each graph.nodes as current,index (`${current.id}:${index}`)}<button aria-pressed={selected===current.id} onclick={()=>selected=current.id}>{workflowNodeName(current.type)}<small>{current.id}</small></button>{/each}</div></section>
      <section aria-label="Draft node inspector"><h2>Selected draft node</h2>{#if node}{@const descriptor=supportedNode(node.type)}<h3>{workflowNodeName(node.type)}</h3><p><code>{node.id}</code> · implementation v{node.version}</p>{#if descriptor}<p class="muted">{descriptor.providerCalls?`At most ${descriptor.providerCalls} provider call per invocation`:'No provider call'} · {descriptor.invocation}</p><h3>Inputs</h3><ul>{#each Object.entries(descriptor.inputs) as [name,port]}<li>{name}: {port.type}{port.alternatives?' · conditional alternatives':' · one connection'}</li>{:else}<li>No inputs</li>{/each}</ul><h3>Outputs</h3><ul>{#each Object.entries(descriptor.outputs) as [name,port]}<li>{name}: {port.type}</li>{/each}</ul>{#if descriptor.binding}<label>Node binding<select aria-label="Node binding" value={node.binding??''} onchange={event=>node!.binding=event.currentTarget.value||undefined}><option value="">Unbound</option>{#each graph.bindings.filter(binding=>binding.kind===descriptor.binding) as binding}<option value={binding.name}>{binding.name}</option>{/each}</select></label>{/if}{:else}<p class="notice">Unsupported built-in type. Remove or replace it.</p>{/if}<button onclick={remove} disabled={graph.nodes.length<=1}>Remove selected node</button>{:else}<p>Select a node from the list.</p>{/if}</section>
    </div>
    <section aria-label="Draft connections"><h2>Typed connections</h2><div class="form-grid"><label>From node<select aria-label="From node" bind:value={fromNode} onchange={()=>fromPort=''}>{#each graph.nodes as node}<option value={node.id}>{node.id}</option>{/each}</select></label><label>Output port<select aria-label="Output port" bind:value={fromPort} onchange={()=>toPort=''}><option value="">Choose output</option>{#each outputs as [name,port]}<option value={name}>{name} · {port.type}</option>{/each}</select></label><label>To node<select aria-label="To node" bind:value={toNode} onchange={()=>toPort=''}>{#each graph.nodes as node}<option value={node.id}>{node.id}</option>{/each}</select></label><label>Input port<select aria-label="Input port" bind:value={toPort}><option value="">Choose compatible input</option>{#each compatible as [name,port]}<option value={name}>{name} · {port.type}</option>{/each}</select></label></div><button onclick={connect} disabled={!type||!compatible.some(([name])=>name===toPort)}>Add connection</button>
      <ul class="edge-list">{#each graph.edges as edge,index}<li><span>{edge.from.node}.{edge.from.port} → {edge.to.node}.{edge.to.port}</span><button aria-label={`Remove connection ${index+1}`} onclick={()=>graph.edges.splice(index,1)}>Remove</button></li>{/each}</ul>
    </section>
    <p class="notice">One bounded repair, existing acceptance policy and serial source scheduling remain fixed. Editing or disconnecting a visible stage cannot change server-side save rules.</p>
  </fieldset>
</main>

<style>
  .preset-editor{max-width:1200px}.preset-editor fieldset{border:0;padding:0;min-width:0}.preset-editor section{min-width:0;margin:24px 0}.preset-list{display:flex;flex-wrap:wrap;gap:8px}.editor-columns{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:28px}.node-list{display:grid;gap:5px;max-height:520px;overflow:auto;margin-top:12px}.node-list button{text-align:left}.node-list small{display:block;color:var(--muted)}button[aria-pressed=true]{border-color:var(--accent);background:var(--panel)}.edge-list{list-style:none;padding:0}.edge-list li{display:flex;gap:12px;align-items:center;justify-content:space-between;padding:7px 0;border-bottom:1px solid var(--line)}.edge-list span{overflow-wrap:anywhere;min-width:0}.edge-list button{flex-shrink:0}.preset-editor code{overflow-wrap:anywhere}
  @media(max-width:700px){.editor-columns{grid-template-columns:minmax(0,1fr)}.edge-list li{align-items:start}.preset-list button{max-width:100%;overflow-wrap:anywhere}}
</style>
